def verify():
    assert abs(K * 1e-12 / 0.09 - 0.1) < 1e-12 and abs(K * 2e-9 / 9 - 2) < 1e-9
    assert abs(math.hypot(2, 4) - 4.472) < 1e-3 and abs(EPS0 / 1e-3 * 1e9 - 8.854) < 1e-3
    assert abs(0.9 / K * 1e12 - 100) < 1e-9 and abs(MU0 * 10 / (2 * math.pi * 0.1) - 2e-5) < 1e-12
    assert abs(MU0 * 100 / (2 * math.pi * 0.1) - 2e-4) < 1e-12 and abs(1.72e-8 * 100 / 1e-6 - 1.72) < 1e-9
    assert abs(math.sqrt(MU0 / EPS0) - 376.7) < 0.2


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
